"""HTTP access to the Internet Archive with retries, backoff and rate limiting.

Error classification is deliberate: the recovery ledger must be able to tell a
*confirmed archive gap* apart from a *timeout*, a *throttle* or a *transport*
failure, because only the former means "stop trying for now".
"""
from __future__ import annotations

import random
import threading
import time
from dataclasses import dataclass, field
from typing import Any, Callable, Optional
from urllib.parse import quote

from . import config

try:  # requests is the fast path; urllib is the offline fallback.
    import requests  # type: ignore
except Exception:  # pragma: no cover - exercised only on bare runners
    requests = None  # type: ignore


# --- failure classes ---------------------------------------------------------
GAP = "archive_gap"            # archive says it has nothing (404 / "not archived")
TIMEOUT = "timeout"            # bounded long timeout hit
THROTTLED = "throttled"        # 429 / 503 / explicit rate-limit page
TRANSPORT = "transport"        # DNS/reset/other network failure
HTTP_ERROR = "http_error"      # other non-200 status
CUTOFF_VIOLATION = "cutoff_violation"  # capture newer than the cutoff
BAD_BODY = "bad_body"          # body is not the media type we asked for
OK = "ok"


class RecoveryError(Exception):
    """Raised for unrecoverable configuration problems (never for gaps)."""

    def __init__(self, message: str, kind: str = TRANSPORT, status: int | None = None):
        super().__init__(message)
        self.kind = kind
        self.status = status


@dataclass
class Response:
    url: str
    status: int | None
    body: bytes = b""
    headers: dict = field(default_factory=dict)
    error: Optional[str] = None      # one of OK, GAP, TIMEOUT, ...
    message: str = ""
    elapsed: float = 0.0
    attempts: int = 1

    @property
    def ok(self) -> bool:
        return self.error == OK

    def text(self, encoding: str = "utf-8") -> str:
        return self.body.decode(encoding, errors="replace")

    def json(self) -> Any:
        import json

        return json.loads(self.text())


class RateLimiter:
    """Simple global minimum spacing between outbound requests."""

    def __init__(self, interval: float = config.MIN_REQUEST_INTERVAL):
        self.interval = interval
        self._last = 0.0
        self._lock = threading.Lock()

    def wait(self) -> None:
        with self._lock:
            now = time.monotonic()
            delay = self.interval - (now - self._last)
            if delay > 0:
                time.sleep(delay)
            self._last = time.monotonic()


class Fetcher:
    """Bounded, retrying HTTP GET. Subclass for offline tests."""

    def __init__(
        self,
        timeout: float = config.DEFAULT_TIMEOUT,
        attempts: int = config.MAX_ATTEMPTS,
        limiter: Optional[RateLimiter] = None,
        sleep: Callable[[float], None] = time.sleep,
    ):
        self.timeout = timeout
        self.attempts = attempts
        self.limiter = limiter if limiter is not None else RateLimiter()
        self.sleep = sleep
        self.session = requests.Session() if requests is not None else None
        if self.session is not None:
            self.session.headers.update({"User-Agent": config.USER_AGENT})
        self.stats: dict[str, int] = {}

    # -- to be provided by tests ------------------------------------------
    def _raw(self, url: str, timeout: float) -> Response:  # pragma: no cover
        raise NotImplementedError

    def _get(self, url: str, timeout: float) -> Response:
        if self.session is not None:
            start = time.monotonic()
            try:
                r = self.session.get(url, timeout=timeout, allow_redirects=True)
                return Response(
                    url=str(r.url),
                    status=r.status_code,
                    body=r.content,
                    headers={k.lower(): v for k, v in r.headers.items()},
                    elapsed=time.monotonic() - start,
                )
            except Exception as exc:  # requests raises many concrete types
                name = type(exc).__name__.lower()
                kind = TIMEOUT if "timeout" in name else TRANSPORT
                return Response(url=url, status=None, error=kind, message=str(exc)[:300])
        return self._urllib_get(url, timeout)

    def _urllib_get(self, url: str, timeout: float) -> Response:  # pragma: no cover
        import urllib.error
        import urllib.request

        req = urllib.request.Request(url, headers={"User-Agent": config.USER_AGENT})
        start = time.monotonic()
        try:
            with urllib.request.urlopen(req, timeout=timeout) as resp:
                body = resp.read()
                return Response(
                    url=resp.geturl(),
                    status=resp.status,
                    body=body,
                    headers={k.lower(): v for k, v in resp.headers.items()},
                    elapsed=time.monotonic() - start,
                )
        except urllib.error.HTTPError as exc:
            body = b""
            try:
                body = exc.read()
            except Exception:
                pass
            return Response(url=url, status=exc.code, body=body, elapsed=time.monotonic() - start)
        except Exception as exc:
            name = type(exc).__name__.lower()
            kind = TIMEOUT if "timeout" in name else TRANSPORT
            return Response(url=url, status=None, error=kind, message=str(exc)[:300])

    # -- retry / classify --------------------------------------------------
    @staticmethod
    def classify(resp: Response) -> Response:
        if resp.error is not None and resp.error != OK:
            return resp
        status = resp.status or 0
        if status == 200:
            resp.error = OK
        elif status in (404, 410):
            resp.error = GAP
            resp.message = resp.message or f"HTTP {status}"
        elif status in (429, 503):
            resp.error = THROTTLED
            resp.message = resp.message or f"HTTP {status}"
        else:
            resp.error = HTTP_ERROR
            resp.message = resp.message or f"HTTP {status}"
        return resp

    def get(
        self,
        url: str,
        *,
        timeout: Optional[float] = None,
        attempts: Optional[int] = None,
        idempotent: bool = True,
    ) -> Response:
        timeout = self.timeout if timeout is None else timeout
        attempts = self.attempts if attempts is None else attempts
        last: Optional[Response] = None
        for attempt in range(1, max(1, attempts) + 1):
            self.limiter.wait()
            resp = self.classify(self._get(url, timeout))
            resp.attempts = attempt
            last = resp
            if resp.ok:
                break
            if not idempotent:
                break
            # Retry only transient classes; a gap or a cutoff violation is final.
            if resp.error in (GAP, CUTOFF_VIOLATION, BAD_BODY, HTTP_ERROR):
                break
            if attempt >= max(1, attempts):
                break
            delay = min(45.0, (2 ** (attempt - 1)) * 3.0) * (0.6 + random.random() * 0.8)
            self.sleep(delay)
        if last is not None:
            self.stats[last.error or "unknown"] = self.stats.get(last.error or "unknown", 0) + 1
        return last  # type: ignore[return-value]

    # -- Wayback-specific --------------------------------------------------
    @staticmethod
    def replay_url(timestamp: str, original: str, mode: str = "id_") -> str:
        """Wayback replay URL. `mode` id_=raw bytes, if_=iframe, ""=toolbar page."""
        if timestamp > config.CUTOFF:
            raise RecoveryError(
                f"capture {timestamp} is newer than cutoff {config.CUTOFF}",
                kind=CUTOFF_VIOLATION,
            )
        return f"{config.REPLAY_BASE}/{timestamp}{mode}/{original}"

    def replay(self, timestamp: str, original: str, mode: str = "id_", **kw) -> Response:
        try:
            url = self.replay_url(timestamp, original, mode)
        except RecoveryError as exc:
            return Response(url=original, status=None, error=exc.kind, message=str(exc))
        resp = self.get(url, **kw)
        resp.url = url
        resp.message = resp.message or ""
        # `id_` replays of missing captures answer with a 200 HTML error page.
        if resp.ok and resp.headers.get("content-type", "").startswith("text/html") and mode == "id_":
            body = resp.text()[:4000]
            if "has not been archived" in body or "does not have a page" in body or "not found" in body.lower()[:400]:
                resp.error = GAP
                resp.message = "replay returned 'not archived' HTML"
        return resp

    def cdx(self, params: dict, **kw) -> Response:
        from urllib.parse import urlencode

        query = dict(params)
        query.setdefault("output", "json")
        return self.get(f"{config.CDX_URL}?{urlencode(query, safe=':*/,')}", **kw)

"""CDX inventory helpers: resumable, cutoff-bounded capture discovery."""
from __future__ import annotations

import json
import os
from dataclasses import dataclass, asdict
from typing import Iterable, Optional

from . import config
from .http import GAP, OK, Fetcher, Response

DEFAULT_FIELDS = "urlkey,timestamp,original,mimetype,statuscode,digest,length,redirect"


@dataclass
class Capture:
    timestamp: str
    original: str
    statuscode: str = ""
    mimetype: str = ""
    digest: str = ""
    length: str = ""
    urlkey: str = ""
    redirect: str = ""
    source_query: str = ""

    @property
    def key(self) -> str:
        return f"{self.timestamp}|{normalize_url(self.original)}"

    def to_row(self) -> dict:
        d = asdict(self)
        return {k: v for k, v in d.items() if v}


def normalize_url(url: str) -> str:
    """Canonical comparison form: no scheme, no default port, lowercase host."""
    u = url.strip()
    for scheme in ("https://", "http://"):
        if u.lower().startswith(scheme):
            u = u[len(scheme):]
            break
    if u.startswith("//"):
        u = u[2:]
    host, _, path = u.partition("/")
    host = host.lower()
    if ":" in host:
        host = host.rsplit(":", 1)[0]
    path = path or "/"
    return f"{host}/{path}" if path != "/" else host


def within_cutoff(timestamp: str, cutoff: str = config.CUTOFF) -> bool:
    return isinstance(timestamp, str) and len(timestamp) >= 14 and timestamp <= cutoff


def parse_cdx_json(rows: list, source_query: str = "") -> list[Capture]:
    """CDX json output: first row is a header when fields are requested."""
    out: list[Capture] = []
    if not rows:
        return out
    header: Optional[list] = None
    first = rows[0]
    if first and isinstance(first[0], str) and first[0] in ("urlkey", "timestamp"):
        header = list(first)
        rows = rows[1:]
    for row in rows:
        if not isinstance(row, (list, tuple)) or not row:
            continue
        if header is None:
            header = DEFAULT_FIELDS.split(",")
            header = header[: len(row)]
        rec = dict(zip(header, [str(v) for v in row]))
        ts = rec.get("timestamp", "")
        if not within_cutoff(ts):
            continue
        out.append(
            Capture(
                timestamp=ts,
                original=rec.get("original", ""),
                statuscode=rec.get("statuscode", ""),
                mimetype=rec.get("mimetype", ""),
                digest=rec.get("digest", ""),
                length=rec.get("length", ""),
                urlkey=rec.get("urlkey", ""),
                redirect=rec.get("redirect", ""),
                source_query=source_query,
            )
        )
    return out


def cdx_query(fetcher: Fetcher, url: str, *, match: str = "prefix", limit: int = 10000,
              extra: Optional[dict] = None) -> tuple[list[Capture], Response]:
    """One CDX query. Returns captures and the raw response for diagnostics."""
    params = {
        "url": url,
        "matchType": match,
        "from": "19960101",
        "to": config.CUTOFF,
        "fl": DEFAULT_FIELDS,
        "limit": str(limit),
    }
    if extra:
        params.update(extra)
    resp = fetcher.cdx(params)
    if not resp.ok:
        return [], resp
    try:
        rows = resp.json()
    except Exception as exc:  # pragma: no cover - defensive
        resp.error = "http_error"
        resp.message = f"bad cdx json: {exc}"
        return [], resp
    return parse_cdx_json(rows, source_query=url), resp


def year_windows(start_year: int = 2007, end_year: int = 2019) -> list[str]:
    """Per-year `from` values so big inventories can resume after interruption."""
    return [f"{y}0101" for y in range(start_year, end_year + 1)]


class CaptureIndex:
    """Append-only JSONL capture inventory with a resumable manifest."""

    def __init__(self, path: str, manifest_path: str | None = None):
        self.path = path
        self.manifest_path = manifest_path or path + ".manifest.json"
        self._keys: set[str] = set()
        os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
        if os.path.exists(path):
            with open(path, encoding="utf-8") as fh:
                for line in fh:
                    line = line.strip()
                    if not line:
                        continue
                    try:
                        rec = json.loads(line)
                    except Exception:
                        continue
                    self._keys.add(f"{rec.get('timestamp')}|{normalize_url(rec.get('original',''))}")
        self.manifest = self._load_manifest()

    def _load_manifest(self) -> dict:
        if os.path.exists(self.manifest_path):
            try:
                with open(self.manifest_path, encoding="utf-8") as fh:
                    return json.load(fh)
            except Exception:
                return {}
        return {"done": {}, "stats": {}}

    def save_manifest(self) -> None:
        tmp = self.manifest_path + ".tmp"
        with open(tmp, "w", encoding="utf-8") as fh:
            json.dump(self.manifest, fh, ensure_ascii=False, indent=2, sort_keys=True)
        os.replace(tmp, self.manifest_path)

    def query_done(self, name: str) -> bool:
        return bool(self.manifest.get("done", {}).get(name))

    def mark_done(self, name: str, info: dict | None = None) -> None:
        self.manifest.setdefault("done", {})[name] = info or {"at": _now()}
        self.save_manifest()

    def add(self, captures: Iterable[Capture]) -> int:
        new = 0
        with open(self.path, "a", encoding="utf-8") as fh:
            for cap in captures:
                if cap.key in self._keys:
                    continue
                self._keys.add(cap.key)
                fh.write(json.dumps(cap.to_row(), ensure_ascii=False) + "\n")
                new += 1
            fh.flush()
            os.fsync(fh.fileno())
        self.manifest.setdefault("stats", {})[os.path.basename(self.path)] = len(self._keys)
        self.save_manifest()
        return new

    def all(self) -> list[Capture]:
        out: list[Capture] = []
        if not os.path.exists(self.path):
            return out
        with open(self.path, encoding="utf-8") as fh:
            for line in fh:
                line = line.strip()
                if not line:
                    continue
                try:
                    rec = json.loads(line)
                except Exception:
                    continue
                out.append(
                    Capture(
                        timestamp=rec.get("timestamp", ""),
                        original=rec.get("original", ""),
                        statuscode=rec.get("statuscode", ""),
                        mimetype=rec.get("mimetype", ""),
                        digest=rec.get("digest", ""),
                        length=rec.get("length", ""),
                        urlkey=rec.get("urlkey", ""),
                        redirect=rec.get("redirect", ""),
                        source_query=rec.get("source_query", ""),
                    )
                )
        return out


def _now() -> str:
    import datetime

    return datetime.datetime.now(datetime.timezone.utc).isoformat(timespec="seconds")

"""Turn an archived Tumblr page into a post record (HTML, text, tags, images).

The parser keeps the *original* inner HTML for post content (found by a balanced
tag scan on the raw response) so Unicode/Hebrew survives byte-for-byte, and
derives a plain-text rendition plus structured image/caption evidence.
"""
from __future__ import annotations

import hashlib
import html as htmllib
import re
from html.parser import HTMLParser
from typing import Iterable, Optional
from urllib.parse import unquote, urlparse

from . import config

VOID_TAGS = {
    "area", "base", "br", "col", "embed", "hr", "img", "input", "link", "meta",
    "param", "source", "track", "wbr",
}

# Class names that hold the post body, in priority order (old then new themes).
CONTENT_SELECTORS = (
    ("div", "copy"),
    ("div", "post-content"),
    ("div", "post_content"),
    ("div", "post-body"),
    ("article", "post-content"),
    ("div", "entry-content"),
)
CAPTION_SELECTORS = (
    ("figcaption", None),
    ("div", "caption"),
    ("p", "caption"),
    ("span", "caption"),
)

EXCLUDE_IMG_HINTS = (
    "avatar", "default_avatar", "impixu", "px.srvcs.tumblr.com", "assets.tumblr.com",
    "fb_share", "addthis", "stat20", "pixel", "tracking", "spacer", "blank.gif",
    "tumblr_avatar", "/images/logo", "gravatar", "b-static", "s24h.ak.tumblr.com",
)

TAGGED_RE = re.compile(r'href="([^"]*?/tagged/[^"?#]+)[^"]*"', re.I)
POST_ID_RE = re.compile(r"/post/(\d+)")
POSTED_TITLE_RE = re.compile(r'title="(Posted on [^"]+)"', re.I)
TIME_RE = re.compile(r'<time[^>]*datetime="([^"]+)"', re.I)
MEDIA_PATH_RE = re.compile(r"/(tumblr_[^/?#]+)\.(jpg|jpeg|png|gif|webp)$", re.I)


# ---------------------------------------------------------------- raw slicing
def _find_open_tag(html: str, tag: str, class_name: Optional[str]) -> Optional[int]:
    """Index of the opening tag for <tag ...> carrying class_name, else None."""
    pattern = re.compile(r"<" + tag + r"\b([^>]*)>", re.I)
    for m in pattern.finditer(html):
        attrs = m.group(1)
        if class_name is None:
            return m.start()
        if re.search(r'class="[^"]*\b' + re.escape(class_name) + r'\b[^"]*"', attrs, re.I):
            return m.start()
    return None


def inner_html(html: str, tag: str, class_name: Optional[str] = None) -> tuple[str, str]:
    """Return (inner_html, outer_start) for the first matching element."""
    start = _find_open_tag(html, tag, class_name)
    if start is None:
        return "", -1
    m = re.match(r"<" + tag + r"\b([^>]*)>", html[start:], re.I)
    if not m:
        return "", -1
    if m.group(0).rstrip().endswith("/>"):
        return "", start
    open_end = start + m.end()
    if class_name is None:
        # For class-less selectors match any tag of that name.
        opener_re = re.compile(r"<" + tag + r"\b([^>]*)>", re.I)
    depth = 1
    pos = open_end
    scan = re.compile(r"<(/?)" + tag + r"\b([^>]*)>", re.I)
    while True:
        m2 = scan.search(html, pos)
        if not m2:
            return html[open_end:], start
        closing = m2.group(1) == "/"
        attrs = m2.group(2)
        self_closing = attrs.rstrip().endswith("/")
        if closing:
            depth -= 1
            if depth == 0:
                return html[open_end:m2.start()], start
            pos = m2.end()
        else:
            if not self_closing and tag.lower() not in VOID_TAGS:
                depth += 1
            pos = m2.end()
        if class_name is not None and not closing:
            # A sibling with a different class does not affect nesting, but an
            # opening tag of the same class at depth 1 is what we track; keep
            # scanning (depth counting above handles it).
            continue


class _TextExtractor(HTMLParser):
    def __init__(self) -> None:
        super().__init__(convert_charrefs=True)
        self.parts: list[str] = []
        self._skip = 0
        self._skip_tags = {"script", "style"}

    def handle_starttag(self, tag, attrs):
        if tag in self._skip_tags:
            self._skip += 1
        if tag in ("br", "p", "div", "li", "tr"):
            self.parts.append("\n")

    def handle_endtag(self, tag):
        if tag in self._skip_tags and self._skip:
            self._skip -= 1
        if tag in ("p", "div", "li", "tr"):
            self.parts.append("\n")

    def handle_data(self, data):
        if self._skip:
            return
        self.parts.append(data)

    def text(self) -> str:
        raw = "".join(self.parts)
        raw = raw.replace("\r\n", "\n").replace("\r", "\n")
        lines = [re.sub(r"[ \t\u00a0]+", " ", ln).strip() for ln in raw.split("\n")]
        return "\n".join([ln for ln in lines if ln])


def html_to_text(fragment: str) -> str:
    p = _TextExtractor()
    try:
        p.feed(fragment or "")
        p.close()
    except Exception:  # pragma: no cover - malformed archived HTML
        return htmllib.unescape(re.sub(r"<[^>]+>", " ", fragment or ""))
    return p.text()


# -------------------------------------------------------------- URL filtering
def host_of(url: str) -> str:
    try:
        return (urlparse(url if "//" in url else "http://" + url).hostname or "").lower()
    except Exception:
        return ""


def is_tumblr_media(url: str) -> bool:
    return bool(re.search(config.MEDIA_HOST_RE, host_of(url)))


def media_key(url: str) -> Optional[str]:
    """tumblr_<name> plus size/extension: the identity of one Tumblr media file."""
    path = urlparse(url).path
    m = MEDIA_PATH_RE.search(path)
    if not m:
        return None
    return m.group(1) + "." + m.group(2).lower()


def base_media_key(url: str) -> Optional[str]:
    """Identity ignoring the size suffix (_500, _1280, ...)."""
    key = media_key(url)
    if not key:
        return None
    stem, _, ext = key.rpartition(".")
    stem = re.sub(r"_\d{2,4}$", "", stem)
    return stem + "." + ext


def is_excluded_image(url: str, attrs: str = "") -> Optional[str]:
    low = (url or "").lower()
    if not low:
        return "empty-src"
    if "avatar" in low or "default_avatar" in low:
        return "avatar"
    for hint in EXCLUDE_IMG_HINTS:
        if hint in low:
            return "excluded:" + hint
    if re.search(r'\bwidth="1"', attrs) and re.search(r'\bheight="1"', attrs):
        return "tracking-pixel"
    return None


def parse_image_variants(url: str) -> list[str]:
    """Candidate archived variants for one Tumblr media file (larger first)."""
    out = [url]
    m = re.match(r"(?P<stem>tumblr_[^/?#]+?)_(?P<size>\d{2,4})\.(?P<ext>jpg|jpeg|png|gif|webp)$",
                 urlparse(url).path, re.I)
    if not m:
        return out
    stem, ext = m.group("stem"), m.group("ext")
    base = url[: urlparse(url).path.rfind("/") + 1]
    for size in ("1280", "1024", "540", "500", "400", "250", "100"):
        cand = f"{base}{stem}_{size}.{ext}"
        if cand not in out:
            out.append(cand)
    for alt_ext in ("png", "gif", "jpg"):
        if alt_ext == ext.lower():
            continue
        cand = f"{base}{stem}.{alt_ext}"
        if cand not in out:
            out.append(cand)
    return out


# ------------------------------------------------------------------ extraction
class _ImageCollector(HTMLParser):
    def __init__(self) -> None:
        super().__init__(convert_charrefs=True)
        self.images: list[dict] = []
        self.links: list[dict] = []
        self._pending: dict | None = None

    def handle_starttag(self, tag, attrs):
        a = {k.lower(): (v or "") for k, v in attrs}
        if tag == "img":
            src = a.get("src") or a.get("data-src") or ""
            entry = {
                "url": src,
                "alt": a.get("alt", ""),
                "title": a.get("title", ""),
                "class": a.get("class", ""),
                "attrs": " ".join(f'{k}="{v}"' for k, v in a.items()),
                "via": "img",
            }
            reason = is_excluded_image(src, entry["attrs"])
            entry["excluded_reason"] = reason
            self.images.append(entry)
            self._pending = entry
        elif tag == "a":
            href = a.get("href", "")
            if href:
                self._pending = {"url": href, "alt": "", "title": a.get("title", ""),
                                 "class": a.get("class", ""), "attrs": "", "via": "a-href",
                                 "excluded_reason": is_excluded_image(href, "")}
                self.links.append(self._pending)

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)

    def handle_endtag(self, tag):
        if tag in ("a", "img"):
            self._pending = None

    def handle_data(self, data):
        if self._pending and data.strip() and self._pending["via"] == "a-href":
            self._pending.setdefault("link_text", data.strip())


def _decode_tag(raw: str) -> str:
    value = unquote(raw)
    return value


def extract_tags(html: str) -> list[str]:
    tags: list[str] = []
    for href in TAGGED_RE.findall(html or ""):
        tag = _decode_tag(href.rsplit("/tagged/", 1)[1].strip("/"))
        tag = htmllib.unescape(tag).strip()
        if tag and tag not in tags:
            tags.append(tag)
    return tags


def extract_images(html: str) -> list[dict]:
    col = _ImageCollector()
    try:
        col.feed(html or "")
        col.close()
    except Exception:  # pragma: no cover
        pass
    og = re.findall(r'<meta[^>]+property="og:image"[^>]+content="([^"]+)"', html or "", re.I)
    ordered: list[dict] = []
    seen: set[str] = set()

    def add(entry: dict, source: str) -> None:
        url = entry.get("url", "")
        if entry.get("excluded_reason"):
            return
        if not is_tumblr_media(url):
            return
        key = media_key(url)
        if not key:
            return
        if key in seen:
            return
        seen.add(key)
        record = {
            "media_url": url,
            "media_key": key,
            "base_key": base_media_key(url),
            "caption_alt": entry.get("alt") or entry.get("title") or "",
            "link_text": entry.get("link_text", ""),
            "found_in": source,
            "variants": parse_image_variants(url),
        }
        ordered.append(record)

    for entry in col.images:
        add(entry, entry.get("via", "img"))
    for entry in col.links:
        if entry.get("url") and is_tumblr_media(entry["url"]):
            add(entry, "photo-link")
    for url in og:
        add({"url": url, "alt": "", "title": "", "excluded_reason": None, "via": "og:image"}, "og:image")
    return ordered


def extract_captions(html: str, images: list[dict]) -> list[str]:
    """Captions that are real evidence: image alt/title, figcaption, caption div."""
    caps: list[str] = []
    for img in images:
        alt = (img.get("caption_alt") or "").strip()
        if alt:
            caps.append(alt)
    for tag, cls in CAPTION_SELECTORS:
        if cls is None:
            continue
        raw, _ = inner_html(html, tag, cls)
        if raw:
            text = html_to_text(raw)
            if text:
                caps.append(text)
    out: list[str] = []
    for c in caps:
        if c and c not in out:
            out.append(c)
    return out


def parse_post_page(html: str, original_url: str, timestamp: str, replay_url: str = "") -> dict:
    """Parse one archived post page into a post record."""
    content_html = ""
    content_source = ""
    outer_start = -1
    for tag, cls in CONTENT_SELECTORS:
        raw, start = inner_html(html, tag, cls)
        if raw and raw.strip():
            content_html, content_source, outer_start = raw, f"{tag}.{cls}", start
            break
    if not content_html:
        post_div, _ = inner_html(html, "div", "post")
        if post_div:
            content_html, content_source = post_div, "div.post"

    images = extract_images(html)
    captions = extract_captions(html, images)
    tags = extract_tags(html)
    posted = POSTED_TITLE_RE.search(html or "")
    posted_on = htmllib.unescape(posted.group(1)) if posted else ""
    dt = TIME_RE.search(html or "")
    date_text = ""
    raw_date, _ = inner_html(html, "div", "date")
    if raw_date:
        date_text = html_to_text(raw_date)
    ids = POST_ID_RE.findall(original_url or "")

    return {
        "post_id": ids[0] if ids else "",
        "original_url": original_url,
        "capture_timestamp": timestamp,
        "replay_url": replay_url or "",
        "page_sha256": hashlib.sha256((html or "").encode("utf-8", "replace")).hexdigest(),
        "page_bytes": len((html or "").encode("utf-8", "replace")),
        "content_html": content_html,
        "content_source": content_source,
        "content_text": html_to_text(content_html) if content_html else "",
        "tags": tags,
        "images": images,
        "captions": captions,
        "posted_on": posted_on,
        "post_datetime": dt.group(1) if dt else "",
        "date_text": date_text,
    }


def post_id_from_url(url: str) -> str:
    m = POST_ID_RE.search(url or "")
    return m.group(1) if m else ""


def merge_records(records: Iterable[dict]) -> dict:
    """Merge several captures of the same post; never downgrade better data."""
    best: Optional[dict] = None
    for rec in records:
        if best is None:
            best = dict(rec)
            continue
        score = record_score(rec)
        if score > record_score(best):
            merged = dict(best)
            merged.update(rec)
            merged["merged_from"] = sorted({best.get("capture_timestamp", ""), rec.get("capture_timestamp", "")})
            best = merged
    return best or {}


def record_score(rec: dict) -> tuple:
    return (
        1 if rec.get("content_text") else 0,
        len(rec.get("content_text") or ""),
        1 if rec.get("images") else 0,
        len(rec.get("images") or []),
        len(rec.get("tags") or []),
        1 if rec.get("captions") else 0,
    )
